<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue';
import UniIcons from '@dcloudio/uni-ui/lib/uni-icons/uni-icons.vue';
import UniNumberBox from '@dcloudio/uni-ui/lib/uni-number-box/uni-number-box.vue';
import { api, useIdentity } from '../../store';
import { ApiError, DEFAULT_ESCORT_TASK, canServe, qualifiedGames, money, compactMoney, statusLabels, serviceLabels, time, orderMembers, participantEarnings, orderSummary, type Game, type Player, type Order, type Wallet, type ClubSettings, type ServiceType, type Application } from '@stellar/core';
const identity=useIdentity();
const tab=ref('home'),selectedGame=ref('all'),serviceType=ref<ServiceType>('hourly'),search=ref(''),statusFilter=ref('all'),orderScope=ref('all');
const games=ref<Game[]>([]),players=ref<Player[]>([]),orders=ref<Order[]>([]),hall=ref<Order[]>([]),wallet=ref<Wallet|null>(null),settings=ref<ClubSettings|null>(null),applications=ref<Application[]>([]);
const loading=ref(true),refreshing=ref(false),busy=ref(false),error=ref('');
type Sheet='accounts'|'player'|'checkout'|'pay'|'order'|'refund'|'finish'|'help'|'apply'|'assistants';
const sheet=ref<Sheet|null>(null),selectedPlayer=ref<Player|null>(null),selectedOrder=ref<Order|null>(null);
const checkoutGame=ref('valorant'),checkoutType=ref<ServiceType>('hourly'),region=ref(''),quantity=ref(1),note=ref(''),task=ref(DEFAULT_ESCORT_TASK),taskPrice=ref('128'),agreed=ref(true);
const refundReason=ref(''),refundAmount=ref(0),finishNote=ref(''),taskConfirmed=ref(false),applyType=ref<ServiceType>('hourly'),applyGames=ref<string[]>([]),introduction=ref('');
const now=ref(Date.now()),toast=ref('');let toastTimer:ReturnType<typeof setTimeout>;let interval:ReturnType<typeof setInterval>;let ticker:ReturnType<typeof setInterval>;
const me=computed(()=>players.value.find(p=>p.userId===identity.session?.userId));
const isMine=(o:Order)=>o.bossId===identity.session?.userId;
const isLead=(o:Order)=>o.playerId===me.value?.id;
const isMember=(o:Order)=>orderMembers(o).some(m=>m.playerId===me.value?.id);
const qualified=(type:ServiceType)=>!!me.value?.approved&&!!me.value.qualifications.includes(type);
const demoAccounts=[{id:'u-boss',name:'林序'},{id:'u-hourly',name:'小屿'},{id:'u-escort',name:'凛'},{id:'u-player',name:'岚'}];
function accountStatus(userId:string){const p=players.value.find(p=>p.userId===userId);const types=p?.approved?p.qualifications:[];return types.includes('hourly')?(types.includes('escort')?'组队与护航资格均已开通':'仅组队资格 · 护航未开通'):(types.includes('escort')?'仅护航资格 · 组队未开通':'无发单或接单资格');}

const displayPlayers=computed(()=>players.value.filter(p=>p.userId!==identity.session?.userId&&p.approved&&p.qualifications.includes(serviceType.value)&&(selectedGame.value==='all'||qualifiedGames(p,serviceType.value).includes(selectedGame.value))&&[p.name,p.subtitle,...p.tags].join(' ').toLowerCase().includes(search.value.toLowerCase())));
const displayHall=computed(()=>hall.value.filter(o=>o.serviceType===serviceType.value&&(selectedGame.value==='all'||o.gameId===selectedGame.value)));
const displayOrders=computed(()=>orders.value.filter(o=>(orderScope.value==='all'||(orderScope.value==='created'?isMine(o):isMember(o)))&&(statusFilter.value==='all'||(statusFilter.value==='refund'?o.refundStatus==='pending':o.status===statusFilter.value))));
const currentGame=computed(()=>games.value.find(g=>g.id===checkoutGame.value));
const checkoutPrice=computed(()=>checkoutType.value==='escort'?Math.round(Number(taskPrice.value)*100):selectedPlayer.value?.price??Math.min(...players.value.filter(p=>p.approved&&p.qualifications.includes('hourly')&&canServe(p,'hourly',checkoutGame.value)).map(p=>p.price),6800));
const checkoutTotal=computed(()=>checkoutPrice.value*(checkoutType.value==='escort'?1:quantity.value));
const assistantCandidates=computed(()=>players.value.filter(p=>p.approved&&p.available&&!p.busy&&canServe(p,'escort',selectedOrder.value?.gameId||'')&&p.userId!==selectedOrder.value?.bossId&&!orderMembers(selectedOrder.value!).some(m=>m.playerId===p.id)));
const gameName=(id:string)=>games.value.find(g=>g.id===id)?.name||id;
const gameColor=(id:string)=>games.value.find(g=>g.id===id)?.color||'#b0a2fc';
const activeCount=computed(()=>orders.value.filter(o=>['waiting','accepted','serving','confirming'].includes(o.status)).length);
const applicationFor=(type:ServiceType)=>applications.value.find(a=>a.serviceType===type);
const applicationLabel=(a?:Application)=>a?({pending:'资料审核中',assessment:'考核进行中',approved:'考核通过',rejected:'未通过 · 可重新申请'}[a.status]):'尚未申请';
const remaining=(o:Order)=>Math.max(0,o.quantity*3600000-(now.value-(o.startedAt??now.value))-(o.demoElapsedMs||0));
const countdown=(o:Order)=>{const m=Math.ceil(remaining(o)/60000);return m>0?`剩余 ${Math.floor(m/60)} 小时 ${m%60} 分钟`:'约定时长已完成';};
function notify(message:string){toast.value=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',3200);}
async function run(job:()=>Promise<void>){if(busy.value)return;busy.value=true;try{await job();}catch(e){notify(e instanceof Error?e.message:'操作失败，请重试');}finally{busy.value=false;}}
async function load(silent=false){if(refreshing.value)return;refreshing.value=true;if(!silent)loading.value=true;try{if(!identity.session)await identity.login('user');const [g,p,o,s,h,w,a]=await Promise.all([api.games(),api.players(),api.orders(),api.settings(),api.orders({scope:'hall'}),api.wallet(),api.applications()]);games.value=g;players.value=p;orders.value=o;settings.value=s;hall.value=h;wallet.value=w;applications.value=a;if(selectedOrder.value)selectedOrder.value=o.find(v=>v.id===selectedOrder.value?.id)||h.find(v=>v.id===selectedOrder.value?.id)||selectedOrder.value;error.value='';}catch(e){if(e instanceof ApiError&&e.code===401){await identity.login('user');refreshing.value=false;await load(silent);return;}error.value=e instanceof Error?e.message:'加载失败';}finally{loading.value=false;refreshing.value=false;}}
async function switchAccount(userId:string){await run(async()=>{await identity.login('user',userId);selectedOrder.value=null;sheet.value=null;await load();notify('已切换体验账号，发单与接单均按考核资格开放');});}
function openPlayer(p:Player){selectedPlayer.value=p;sheet.value='player';}
function publishGames(type:ServiceType,p?:Player|null){return me.value?qualifiedGames(me.value,type).filter(id=>!p||qualifiedGames(p,type).includes(id)):[];}
function book(p?:Player){
  if(!qualified(serviceType.value)){openApply(serviceType.value);return;}
  const allowed=publishGames(serviceType.value,p);if(!allowed.length){notify('你与该队友暂无共同通过考核的游戏');return;}
  if(selectedGame.value!=='all'&&!allowed.includes(selectedGame.value)){notify('尚未取得该游戏的发单资格，请选择已认证游戏');return;}
  selectedPlayer.value=p||null;checkoutType.value=serviceType.value;selectGame(selectedGame.value==='all'?allowed[0]:selectedGame.value);quantity.value=1;note.value='';task.value=DEFAULT_ESCORT_TASK;taskPrice.value='128';agreed.value=true;sheet.value='checkout';
}
function chooseCheckoutType(type:ServiceType){if(!qualified(type)){openApply(type);return;}const allowed=publishGames(type,selectedPlayer.value);if(!allowed.length){notify('暂无共同通过考核的游戏');return;}checkoutType.value=type;selectGame(allowed[0]);}
function selectGame(id:string){checkoutGame.value=id;region.value=games.value.find(g=>g.id===id)?.regions[0]||'';}
async function createOrder(){await run(async()=>{if(!me.value||!canServe(me.value,checkoutType.value,checkoutGame.value)){notify('请先通过对应类型与游戏的考核，取得发单资格');return;}if(checkoutType.value==='escort'&&!task.value.trim()){notify('请填写护航任务项');return;}if(!agreed.value){notify('请先确认服务说明');return;}selectedOrder.value=await api.createOrder({serviceType:checkoutType.value,task:task.value,taskPrice:Math.round(Number(taskPrice.value)*100),gameId:checkoutGame.value,region:region.value,quantity:checkoutType.value==='escort'?1:quantity.value,playerId:selectedPlayer.value?.id,note:note.value});await load(true);sheet.value='pay';});}
function payOrder(o:Order){if(!qualified(o.serviceType)){openApply(o.serviceType);return;}if(!me.value||!canServe(me.value,o.serviceType,o.gameId)){notify('尚未取得该游戏的发单资格');return;}selectedOrder.value=o;sheet.value='pay';}
function openOrder(o:Order){selectedOrder.value=o;sheet.value='order';}
async function action(name:string,o=selectedOrder.value,body?:unknown){if(!o)return;await run(async()=>{selectedOrder.value=await api.act(o.id,name,body);await load(true);sheet.value='order';if(name==='pay'||name==='accept')tab.value='orders';notify(({pay:'模拟支付成功，等待接单',accept:'接单成功',start:'服务已开始，协作名单已锁定',finish:'已提交，等待下单用户确认',confirm:'订单已完成',refund:'退款申请已提交','add-assistant':'副手已加入，净报酬按人数均分','demo-elapse':'已模拟完成约定时长'} as Record<string,string>)[name]||'操作成功');});}
function refund(o:Order){selectedOrder.value=o;refundReason.value='';refundAmount.value=o.amount/100;sheet.value='refund';}
function finish(o:Order){selectedOrder.value=o;finishNote.value='';taskConfirmed.value=false;sheet.value='finish';}
function openApply(type:ServiceType){const current=applicationFor(type);if(['pending','assessment'].includes(current?.status||'')){sheet.value=null;tab.value='me';notify('该类型正在审核或考核中，可在此查看进度');return;}applyType.value=type;applyGames.value=[];introduction.value='';sheet.value='apply';}
function toggleGame(id:string){applyGames.value=applyGames.value.includes(id)?applyGames.value.filter(g=>g!==id):[...applyGames.value,id];}
async function submitApplication(){await run(async()=>{await api.apply({serviceType:applyType.value,gameIds:applyGames.value,introduction:introduction.value});await load(true);sheet.value=null;tab.value='me';notify('申请已提交，资料审核后安排考核');});}
async function availability(){await run(async()=>{await api.availability(!me.value?.available);await load(true);notify(me.value?.available?'已开启接单':'已切换为休息状态');});}
function navigate(next:string){tab.value=next;statusFilter.value='all';}
const tabs=[{id:'home',label:'发现',icon:'home'},{id:'hall',label:'接单',icon:'flag'},{id:'orders',label:'订单',icon:'list'},{id:'wallet',label:'报酬',icon:'wallet'},{id:'me',label:'我的',icon:'person'}];
onMounted(async()=>{await load();interval=setInterval(()=>load(true),10000);ticker=setInterval(()=>now.value=Date.now(),1000);});
onUnmounted(()=>{clearInterval(interval);clearInterval(ticker);clearTimeout(toastTimer);});
</script>

<template>
  <view class="mobile-app">
    <view class="topbar"><view class="wordmark"><view class="star-mark">✳</view><view>{{settings?.name||'星曜电竞'}}<text>STELLAR CLUB</text></view></view><button class="role-pill" :disabled="loading" @tap="sheet='accounts'"><view class="live-dot"/>{{identity.session?.name||'用户'}}<uni-icons type="bottom" color="#bfc1ca" :size="11"/></button><button class="icon-btn" aria-label="帮助" @tap="sheet='help'"><uni-icons type="headphones" color="#d8dae3" :size="23"/></button></view>
    <view class="demo-strip"><view class="demo-dot"/> 演示模式 · 不产生真实扣款 <button :disabled="loading" @tap="sheet='accounts'">体验账号</button></view>
    <view v-if="error" class="error-box">{{error}}<button @tap="load()">重新加载</button></view>
    <view v-if="loading" class="loading"><view class="loading-ring"/> 正在加载…</view>
    <view v-else-if="tab==='home'||tab==='hall'" class="content">
      <view class="greeting">{{tab==='home'?'GOOD GAMES, GOOD COMPANY':'PLAY WITH PURPOSE'}}</view><view class="page-title">{{tab==='home'?'好游戏，一起出发':'发现新的协作'}}</view>
      <view v-if="tab==='home'" class="hero-banner"><view class="hero-copy"><view class="hero-kicker">YOUR NEXT GOOD GAME</view><view class="hero-title">默契相遇<br/>精彩加倍。</view><view class="hero-sub">按时组队，或携手完成目标。</view><button class="primary compact" @tap="book()">{{qualified(serviceType)?'发布订单':'申请'+(serviceType==='escort'?'护航':'组队')+'资格'}} <uni-icons type="arrow-right" :size="18" color="#11150c"/></button></view><view class="hero-orbit orbit-one"/><view class="hero-orbit orbit-two"/><view class="hero-spark">✳</view></view>
      <view class="service-switch"><button :class="{active:serviceType==='hourly'}" @tap="serviceType='hourly'"><text>组队订单</text><text>约定时长 · 轻松同行</text></button><button :class="{active:serviceType==='escort'}" @tap="serviceType='escort'"><text>护航订单</text><text>指定任务 · 目标达成</text></button></view>
      <scroll-view scroll-x class="game-scroll"><view class="game-filter"><button :class="{active:selectedGame==='all'}" @tap="selectedGame='all'">全部游戏</button><button v-for="g in games" :key="g.id" :class="{active:selectedGame===g.id}" @tap="selectedGame=g.id">{{g.name}}</button></view></scroll-view>
      <template v-if="tab==='home'"><view class="section-top"><view class="section-title">{{serviceType==='escort'?'可靠的护航伙伴':'发现默契队友'}}</view><text class="muted">已通过入驻考核</text></view><view class="search-box"><uni-icons type="search" color="#858a9d" :size="20"/><input v-model="search" placeholder="搜索昵称、游戏或风格"/></view>
        <view class="player-grid"><view v-for="p in displayPlayers" :key="p.id" class="player-card" @tap="openPlayer(p)"><view class="portrait" :style="{'--portrait-color':p.color}"><view class="portrait-halo"/><view class="portrait-head"/><view class="portrait-body"/><text>{{p.avatar}}</text><view class="online-tag" :class="{offline:!p.available}"><view/>{{p.available?'可预约':'休息中'}}</view></view><view class="player-info"><view class="player-name">{{p.name}}<text class="rating">★ {{p.rating}}</text></view><view class="player-subtitle">{{p.subtitle}}</view><view class="tags"><text v-for="t in p.tags" :key="t">{{t}}</text></view><view class="player-bottom"><view class="price"><template v-if="serviceType==='hourly'">¥{{compactMoney(p.price)}}<text>/小时</text></template><text v-else>按指定任务下单</text></view><button class="invite-btn" aria-label="查看队友" @tap.stop="openPlayer(p)"><uni-icons type="arrow-right" color="#171b13" :size="16"/></button></view></view></view></view><view v-if="!displayPlayers.length" class="empty">暂时没有符合条件的队友</view>
      </template>
      <template v-else><view class="receiving-bar"><view><view>{{qualified(serviceType)?(me?.available?'正在接收新订单':'当前为休息状态'):'开启你的协作之旅'}}</view><text>{{qualified(serviceType)?'已开通对应游戏的发单与接单资格':'通过该类型考核后，才能发布与接取对应订单'}}</text></view><button class="secondary small" @tap="qualified(serviceType)?availability():openApply(serviceType)">{{qualified(serviceType)?(me?.available?'休息一下':'开始接单'):'申请入驻'}}</button></view><view class="section-top"><view class="section-title">{{serviceLabels[serviceType]}}</view><text class="muted">{{displayHall.length}} 个机会</text></view>
        <view v-for="o in displayHall" :key="o.id" class="order-card"><view class="order-top"><view class="game-label"><view class="mini-game" :style="{background:gameColor(o.gameId)+'20',color:gameColor(o.gameId)}">{{games.find(g=>g.id===o.gameId)?.short}}</view>{{o.gameName}}</view><text class="type-badge" :class="o.serviceType">{{serviceLabels[o.serviceType]}}</text></view><view class="job-task">{{orderSummary(o)}}</view><view class="muted">{{o.region}} · {{o.bossName}}<text v-if="o.preferredPlayerId"> · 指定邀请</text></view><view v-if="o.note" class="job-note">{{o.note}}</view><view class="job-footer"><view class="price">¥{{money(o.earnings)}}<text>{{o.serviceType==='escort'?'团队净报酬':'预计净报酬'}}</text></view><button class="primary small" :disabled="busy||(qualified(o.serviceType)&&!!me&&!canServe(me,o.serviceType,o.gameId))" @tap="qualified(o.serviceType)?action('accept',o):openApply(o.serviceType)">{{qualified(o.serviceType)?(me&&canServe(me,o.serviceType,o.gameId)?'接取订单':'未认证此游戏'):'申请考核资格'}}</button></view></view><view v-if="!displayHall.length" class="empty">当前分类暂无待接订单<text>可以切换游戏，或稍后再来看看</text></view>
      </template>
    </view>
    <view v-else-if="tab==='orders'" class="content"><view class="section-top"><view class="page-title">我的订单</view><button class="icon-btn" aria-label="刷新订单" @tap="load(true)"><uni-icons type="refreshempty" color="#bec1ce" :size="24"/></button></view><view class="choice-row order-scope"><button v-for="item in [{id:'all',label:'全部订单'},{id:'created',label:'我发布的'},{id:'joined',label:'我参与的'}]" :key="item.id" :class="{selected:orderScope===item.id}" @tap="orderScope=item.id">{{item.label}}</button></view><scroll-view scroll-x class="order-tabs"><view class="order-tabs-inner"><button v-for="f in [{id:'all',label:'全部'},{id:'unpaid',label:'待付款'},{id:'waiting',label:'待接单'},{id:'accepted',label:'待开始'},{id:'serving',label:'服务中'},{id:'confirming',label:'待确认'},{id:'completed',label:'已完成'},{id:'refund',label:'售后'}]" :key="f.id" :class="{active:statusFilter===f.id}" @tap="statusFilter=f.id">{{f.label}}</button></view></scroll-view>
      <view v-for="o in displayOrders" :key="o.id" class="order-card" @tap="openOrder(o)"><view class="order-top"><view class="game-label">{{o.gameName}}<text class="type-badge" :class="o.serviceType">{{o.serviceType==='escort'?'护航':'组队'}}</text></view><text class="status" :class="o.refundStatus==='pending'?'refund':o.status">{{o.refundStatus==='pending'?'售后处理中':statusLabels[o.status]}}</text></view><view class="job-task">{{orderSummary(o)}}</view><view class="muted">{{o.region}} · {{isMine(o)?'我发布的':'我参与的'}} · {{orderMembers(o).map(m=>m.name).join('、')||'等待接单'}}</view><view class="order-meta"><text>{{time(o.createdAt)}}</text><text>¥{{money(isMine(o)?o.amount:participantEarnings(o,me?.id))}}</text></view><view class="order-actions" @tap.stop><button class="secondary small" @tap="openOrder(o)">查看详情</button><button v-if="isMine(o)&&o.status==='unpaid'" class="primary small" @tap="payOrder(o)">{{qualified(o.serviceType)?'去付款':'申请发单资格'}}</button><button v-if="isLead(o)&&o.serviceType==='escort'&&o.status==='accepted'&&o.refundStatus!=='pending'" class="primary small" @tap="selectedOrder=o;sheet='assistants'">添加副手</button><button v-if="isMine(o)&&o.status==='confirming'&&o.refundStatus!=='pending'" class="primary small" @tap="action('confirm',o)">确认完成</button></view></view><view v-if="!displayOrders.length" class="empty">这里还没有订单<button class="primary compact" @tap="navigate('home')">发布第一笔订单</button></view>
    </view>
    <view v-else-if="tab==='wallet'" class="content"><view class="greeting">YOUR EFFORT, REWARDED</view><view class="page-title">我的报酬</view><view class="income-card"><view class="muted">累计已完成净报酬（元）</view><view class="income-amount">{{money(wallet?.total||0)}}</view><view class="income-row"><view>待结算<text>¥{{money(wallet?.pending||0)}}</text></view><view>已结算<text>¥{{money(wallet?.settled||0)}}</text></view></view></view><view class="notice"><uni-icons type="info" color="#c0b4ff" :size="18"/><text>护航协作按成员人数均分扣除服务费后的净报酬；不足一分的尾差按成员顺序补齐。售后期间暂缓结算。</text></view><view class="section-top"><view class="section-title">报酬明细</view></view><view v-for="o in wallet?.orders" :key="o.id" class="income-item" @tap="openOrder(o)"><view class="income-item-info"><view>{{o.gameName}} · {{serviceLabels[o.serviceType]}}</view><text>{{orderMembers(o).length}} 人参与 · {{time(o.createdAt)}}</text></view><view class="income-plus">+{{money(participantEarnings(o,me?.id))}}</view></view><view v-if="!wallet?.orders.length" class="empty">完成订单后，你的报酬会出现在这里。</view><view class="section-top" v-if="wallet?.settlements.length"><view class="section-title">结算记录</view></view><view v-for="s in wallet?.settlements" :key="s.id" class="income-item"><view class="income-item-info"><view>{{s.status==='paid'?'已模拟付款':'财务待付款'}}</view><text>{{s.orderIds.length}} 笔 · {{time(s.createdAt)}}</text></view><view>¥{{money(s.amount)}}</view></view></view>
    <view v-else class="content profile-page"><view class="greeting">YOUR SPACE, YOUR PACE</view><view class="profile-header"><view class="profile-avatar">{{identity.session?.name.slice(0,1)}}</view><view><view class="profile-name">{{identity.session?.name}}<view class="profile-level">星曜用户</view></view><view class="muted">发布需求，也让你的实力被看见</view></view></view><view class="profile-stats"><view><text>{{orders.length}}</text>全部订单</view><view><text>{{activeCount}}</text>进行中</view><view><text>{{orders.filter(o=>o.status==='completed').length}}</text>已完成</view></view><view class="section-top"><view class="section-title">发单与接单资格</view><text class="muted">资料审核 + 专项考核</text></view><view v-for="type in (['hourly','escort'] as ServiceType[])" :key="type" class="qualification-card"><view class="qualification-top"><view><view>{{type==='escort'?'护航资格':'组队资格'}}</view><text>{{type==='escort'?'独立护航考核 · 按任务验收':'独立组队考核 · 按时长完成'}}</text></view><text class="type-badge" :class="type">{{qualified(type)?'已认证':applicationLabel(applicationFor(type))}}</text></view><view v-if="applicationFor(type)?.reviewNote" class="review-feedback">{{applicationFor(type)?.reviewNote}}<text v-if="applicationFor(type)?.score!==undefined"> · {{applicationFor(type)?.score}} 分</text></view><button v-if="!qualified(type)" class="secondary full" :disabled="['pending','assessment'].includes(applicationFor(type)?.status||'')" @tap="openApply(type)">{{['pending','assessment'].includes(applicationFor(type)?.status||'')?'等待审核与考核':'申请入驻'}}</button><view v-else class="muted">已开通发单与接单：{{(me?qualifiedGames(me,type):[]).map(gameName).join('、')}}</view><view v-if="!qualified(type)" class="input-help">该类型暂未开通发单及接单权限</view></view><view class="profile-menu"><button @tap="navigate('orders')"><uni-icons type="list" :size="21" color="#bdb5f5"/><text>我的订单</text><uni-icons type="arrow-right" color="#7b7f90" :size="15"/></button><button @tap="sheet='accounts'"><uni-icons type="loop" :size="21" color="#bdb5f5"/><text>切换体验账号</text><uni-icons type="arrow-right" color="#7b7f90" :size="15"/></button><button @tap="sheet='help'"><uni-icons type="headphones" :size="21" color="#bdb5f5"/><text>帮助与客服</text><uni-icons type="arrow-right" color="#7b7f90" :size="15"/></button></view><view class="profile-about"><view class="small-star">✳</view><text>STELLAR CLUB</text><view>好游戏，好队友。</view><text class="version">交互体验版 v2.0 · 数据仅保存在当前浏览器</text></view></view>
    <view class="bottom-nav"><button v-for="item in tabs" :key="item.id" :class="{active:tab===item.id}" @tap="navigate(item.id)"><view class="nav-icon"><uni-icons :type="item.icon" :color="tab===item.id?'#d9fd88':'#777c8b'" :size="23"/><view v-if="item.id==='orders'&&activeCount" class="nav-badge">{{activeCount}}</view></view><text>{{item.label}}</text><view v-if="tab===item.id" class="nav-indicator"/></button></view>
    <view v-if="sheet" class="sheet-mask" @tap="sheet=null"><view class="sheet sheet-tall" @tap.stop><view class="sheet-handle"/><button class="sheet-close" aria-label="关闭弹窗" @tap="sheet=null"><uni-icons type="closeempty" color="#a4a8b7" :size="24"/></button>
      <view v-if="sheet==='accounts'" class="sheet-content"><view class="eyebrow">ONE ACCOUNT, MORE POSSIBILITIES</view><view class="sheet-title">选择体验账号</view><view class="sheet-sub">组队与护航分别考核，通过后开通对应类型的发单与接单资格。</view><button v-for="account in demoAccounts" :key="account.id" class="role-card" :class="{chosen:identity.session?.userId===account.id}" :disabled="busy" @tap="switchAccount(account.id)"><view class="role-icon">{{account.name.slice(0,1)}}</view><view><view>{{account.name}}</view><text>{{accountStatus(account.id)}}</text></view><uni-icons type="arrow-right" color="#a5a8b5" :size="20"/></button><view class="sheet-footnote">模拟账号，无需真实微信或手机号。</view></view>
      <view v-else-if="sheet==='player'&&selectedPlayer" class="sheet-content"><view class="player-detail-header"><view class="portrait large" :style="{'--portrait-color':selectedPlayer.color}"><view class="portrait-halo"/><view class="portrait-head"/><view class="portrait-body"/><text>{{selectedPlayer.avatar}}</text></view><view><view class="sheet-title">{{selectedPlayer.name}} <text class="verified">✓</text></view><view class="sheet-sub">{{selectedPlayer.subtitle}}</view><view class="tags"><text v-for="t in selectedPlayer.tags" :key="t">{{t}}</text></view></view></view><view class="detail-stats"><view><text>{{selectedPlayer.rating}}</text>服务评分</view><view><text>{{selectedPlayer.completed}}</text>已完成订单</view><view><text>{{selectedPlayer.available?'在线':'休息'}}</text>接单状态</view></view><view class="form-label">关于我</view><view class="detail-bio">{{selectedPlayer.bio}}</view><view class="form-label">支持的游戏</view><view class="tags"><text v-for="id in selectedPlayer.gameIds" :key="id">{{gameName(id)}}</text></view><view class="service-promise">✓ 已通过{{serviceType==='escort'?'护航':'组队'}}考核 · 服务问题可申请售后</view><button class="primary full" :disabled="!selectedPlayer.available" @tap="book(selectedPlayer)">{{selectedPlayer.available?'邀请一起出发':'队友休息中'}}</button></view>
      <view v-else-if="sheet==='checkout'" class="sheet-content"><view class="eyebrow">START SOMETHING GOOD</view><view class="sheet-title">发布订单</view><view class="sheet-sub">{{selectedPlayer?'指定邀请 · '+selectedPlayer.name:'发布至大厅，等待合适的队友'}}</view><view class="form-label">服务类型</view><view class="choice-row"><button v-for="type in (['hourly','escort'] as ServiceType[])" :key="type" :class="{selected:checkoutType===type}" :disabled="!!selectedPlayer&&!selectedPlayer.qualifications.includes(type)" @tap="chooseCheckoutType(type)">{{serviceLabels[type]}}</button></view><view class="form-label">游戏与区服</view><view class="choice-row"><button v-for="g in games.filter(g=>publishGames(checkoutType,selectedPlayer).includes(g.id))" :key="g.id" :class="{selected:checkoutGame===g.id}" @tap="selectGame(g.id)">{{g.name}}</button></view><view class="choice-row"><button v-for="r in currentGame?.regions" :key="r" :class="{selected:region===r}" @tap="region=r">{{r}}</button></view><template v-if="checkoutType==='escort'"><view class="form-label">任务项 <text>必填</text></view><textarea v-model="task" class="text-area" placeholder="例如：100w纯带出（必填，可修改）" :maxlength="200"/><view class="form-label">整单金额（元）</view><input v-model="taskPrice" class="form-input" type="digit" placeholder="1～1000 元"/><view class="input-help">按任务计价；完成指定任务后提交验收，可由多位认证成员协作。</view></template><view v-else class="form-inline"><view><view class="form-label">约定服务时长</view><view class="muted">¥{{compactMoney(checkoutPrice)}} / 小时</view></view><view class="quantity-control"><uni-number-box v-model="quantity" :min="1" :max="8" background="#2b2d39" color="#f5f5f5"/><text>小时</text></view></view><view class="form-label">补充说明 <text>选填</text></view><textarea v-model="note" class="text-area" placeholder="希望开始的时间、游戏偏好等" :maxlength="200"/><button class="agreement" @tap="agreed=!agreed"><view class="checkmark" :class="{checked:agreed}">{{agreed?'✓':''}}</view><text>{{checkoutType==='escort'?'按指定任务验收，服务问题可申请售后。':'按约定时长履约，服务问题可申请售后。'}}</text></button><view class="sheet-bottom"><view class="total-price"><text>合计</text>¥{{money(checkoutTotal||0)}}</view><button class="primary" :disabled="busy" @tap="createOrder">提交订单</button></view></view>
      <view v-else-if="sheet==='pay'&&selectedOrder" class="sheet-content payment-sheet"><view class="pay-icon"><uni-icons type="weixin" :size="42" color="#72e2a0"/></view><view class="sheet-title">微信支付 · 模拟收银台</view><view class="sheet-sub">{{selectedOrder.gameName}} · {{serviceLabels[selectedOrder.serviceType]}}</view><view class="pay-amount"><text>¥</text>{{money(selectedOrder.amount)}}</view><view class="simulation-note">这是交互演示，不会发起真实扣款。</view><button class="primary full" :disabled="busy" @tap="action('pay')">确认模拟支付</button><button class="text-button" @tap="sheet='order';tab='orders'">稍后支付</button></view>
      <view v-else-if="sheet==='order'&&selectedOrder" class="sheet-content"><view class="eyebrow">ORDER DETAILS</view><view class="sheet-title">{{selectedOrder.refundStatus==='pending'?'售后处理中':statusLabels[selectedOrder.status]}}</view><view class="sheet-sub">{{selectedOrder.id}}</view><view class="detail-order-game"><view class="mini-game big" :style="{background:gameColor(selectedOrder.gameId)+'22',color:gameColor(selectedOrder.gameId)}">{{games.find(g=>g.id===selectedOrder?.gameId)?.short}}</view><view><view>{{selectedOrder.gameName}}</view><text>{{selectedOrder.region}} · {{serviceLabels[selectedOrder.serviceType]}}</text></view><view class="detail-order-price">¥{{money(selectedOrder.amount)}}</view></view><view class="detail-note">{{selectedOrder.serviceType==='escort'?'任务项：':''}}{{orderSummary(selectedOrder)}}</view><view class="detail-row"><text>下单用户</text><text>{{selectedOrder.bossName}}</text></view><view class="detail-row"><text>接单负责人</text><text>{{selectedOrder.playerName||selectedOrder.preferredPlayerName||'等待接单'}}</text></view><view v-if="selectedOrder.note" class="detail-note">{{selectedOrder.note}}</view><template v-if="orderMembers(selectedOrder).length"><view class="form-label">{{selectedOrder.serviceType==='escort'?'协作成员 · 净报酬均分':'服务队友'}}</view><view v-for="(member,i) in orderMembers(selectedOrder)" :key="member.playerId" class="team-member"><view><view>{{member.name}} <text class="muted">{{i===0?'负责人':'副手'}}</text></view><text class="muted">{{member.settlementId?'已进入结算批次':'完成后进入待结算'}}</text></view><text class="lime">¥{{money(participantEarnings(selectedOrder,member.playerId))}}</text><button v-if="i>0&&isLead(selectedOrder)&&selectedOrder.status==='accepted'&&selectedOrder.refundStatus!=='pending'" class="text-button" :disabled="busy" @tap="action('remove-assistant',selectedOrder,{playerId:member.playerId})">移除</button></view><button v-if="isLead(selectedOrder)&&selectedOrder.serviceType==='escort'&&selectedOrder.status==='accepted'&&selectedOrder.refundStatus!=='pending'" class="secondary full" @tap="sheet='assistants'">＋ 添加副手</button><view v-if="selectedOrder.serviceType==='escort'" class="input-help">净报酬 ¥{{money(selectedOrder.earnings)}}，按 {{orderMembers(selectedOrder).length}} 人均分。开始服务后名单锁定，成员均可查看订单及本人报酬。</view></template>
        <view v-if="selectedOrder.serviceType==='hourly'&&selectedOrder.status==='serving'" class="notice"><text>{{countdown(selectedOrder)}}</text><button v-if="isLead(selectedOrder)&&remaining(selectedOrder)>0" class="text-button" :disabled="busy||selectedOrder.refundStatus==='pending'" @tap="action('demo-elapse')">模拟走满时长</button></view><view v-if="selectedOrder.refundStatus!=='none'" class="refund-info"><view>售后：{{selectedOrder.refundStatus==='pending'?'待审核':selectedOrder.refundStatus==='refunded'?'已模拟退款':'未通过'}}</view><text>申请 ¥{{money(selectedOrder.refundAmount||0)}} · {{selectedOrder.refundReason}}</text><text v-if="selectedOrder.refundReviewNote">{{selectedOrder.refundReviewNote}}</text></view><view class="form-label">订单动态</view><view class="timeline"><view v-for="(e,i) in selectedOrder.timeline" :key="i" class="timeline-item"><view class="timeline-dot"/><view><view>{{e.label}}</view><text>{{time(e.at)}} · {{e.actor}}</text><view v-if="e.note" class="timeline-note">{{e.note}}</view></view></view></view><view class="detail-actions"><button class="secondary" @tap="sheet='help'">联系客服</button><template v-if="isMine(selectedOrder)"><button v-if="selectedOrder.status==='unpaid'" class="secondary" :disabled="busy" @tap="action('cancel')">取消订单</button><button v-if="selectedOrder.status==='unpaid'" class="primary" @tap="payOrder(selectedOrder)">{{qualified(selectedOrder.serviceType)?'去付款':'申请发单资格'}}</button><button v-if="selectedOrder.status==='confirming'&&selectedOrder.refundStatus!=='pending'" class="primary" :disabled="busy" @tap="action('confirm')">确认完成</button><button v-if="selectedOrder.paidAt&&selectedOrder.status!=='cancelled'&&['none','rejected'].includes(selectedOrder.refundStatus)&&!selectedOrder.settlementId" class="secondary" @tap="refund(selectedOrder)">申请退款</button></template><template v-if="isLead(selectedOrder)&&selectedOrder.refundStatus!=='pending'"><button v-if="selectedOrder.status==='accepted'" class="primary" :disabled="busy" @tap="action('start')">开始服务</button><button v-if="selectedOrder.status==='serving'" class="primary" :disabled="busy||(selectedOrder.serviceType==='hourly'&&remaining(selectedOrder)>0)" @tap="finish(selectedOrder)">{{selectedOrder.serviceType==='escort'?'提交任务验收':'提交完成'}}</button></template></view></view>
      <view v-else-if="sheet==='assistants'&&selectedOrder" class="sheet-content"><view class="eyebrow">BETTER AS A TEAM</view><view class="sheet-title">添加副手</view><view class="sheet-sub">护航考核通过且支持该游戏的在线成员。加入后均分净报酬，开始服务后锁定名单。</view><button v-for="p in assistantCandidates" :key="p.id" class="role-card" :disabled="busy" @tap="action('add-assistant',selectedOrder,{playerId:p.id})"><view class="role-icon">{{p.name.slice(0,1)}}</view><view><view>{{p.name}}</view><text>{{p.subtitle}}</text></view><text>＋</text></button><view v-if="!assistantCandidates.length" class="empty">暂无可添加成员</view></view>
      <view v-else-if="sheet==='apply'" class="sheet-content"><view class="eyebrow">LET YOUR SKILLS SHINE</view><view class="sheet-title">申请{{applyType==='escort'?'护航':'组队'}}资格</view><view class="sheet-sub">提交申请 → 资料审核 → 专项考核 → 开通发单与接单</view><view class="form-label">申请游戏 <text>可多选</text></view><view class="choice-row"><button v-for="g in games" :key="g.id" :class="{selected:applyGames.includes(g.id)}" @tap="toggleGame(g.id)">{{g.name}}</button></view><view class="form-label">游戏经验与服务说明</view><textarea v-model="introduction" class="text-area" placeholder="介绍你的游戏经验、擅长内容及可参加考核的时间，至少 10 字。" :maxlength="500"/><view class="simulation-note">组队与护航分别申请、分别考核，互不通用。未申请、审核中、考核中或未通过时，该类型均不能发单及接单。通过后仅开通本次考核游戏的权限。</view><button class="primary full" :disabled="busy" @tap="submitApplication">提交申请</button></view>
      <view v-else-if="sheet==='refund'&&selectedOrder" class="sheet-content"><view class="sheet-title">申请售后退款</view><view class="sheet-sub">俱乐部会核实服务记录并处理你的申请。</view><view class="form-label">退款金额（元）</view><input v-model="refundAmount" class="form-input" type="digit"/><view class="input-help">最高 ¥{{money(selectedOrder.amount)}}，支持部分退款。</view><view class="form-label">退款原因</view><textarea v-model="refundReason" class="text-area" placeholder="请说明遇到的问题，至少 5 字" :maxlength="200"/><button class="primary full" :disabled="busy" @tap="action('refund',selectedOrder,{amount:Math.round(Number(refundAmount)*100),reason:refundReason})">提交退款申请</button></view>
      <view v-else-if="sheet==='finish'&&selectedOrder" class="sheet-content"><view class="eyebrow">GG, WELL PLAYED</view><view class="sheet-title">{{selectedOrder.serviceType==='escort'?'提交任务验收':'提交服务记录'}}</view><view class="sheet-sub">提交后由下单用户确认，随后报酬进入待结算。</view><view v-if="selectedOrder.serviceType==='escort'" class="detail-note">任务项：{{selectedOrder.task}}</view><view class="form-label">完成记录</view><textarea v-model="finishNote" class="text-area" :placeholder="selectedOrder.serviceType==='escort'?'说明任务达成情况及验收依据':'说明已完成的服务时长与情况'" :maxlength="200"/><button v-if="selectedOrder.serviceType==='escort'" class="agreement" @tap="taskConfirmed=!taskConfirmed"><view class="checkmark" :class="{checked:taskConfirmed}">{{taskConfirmed?'✓':''}}</view><text>确认已完成订单约定的指定任务</text></button><button class="primary full" :disabled="busy" @tap="action('finish',selectedOrder,{note:finishNote,taskCompleted:taskConfirmed})">提交完成</button></view>
      <view v-else-if="sheet==='help'" class="sheet-content"><view class="eyebrow">ALWAYS ON YOUR SIDE</view><view class="sheet-title">帮助与客服</view><view class="sheet-sub">服务遇到问题，可在订单详情申请售后。</view><view class="help-card"><uni-icons type="headphones" :size="35" color="#d9fd88"/><view><view>俱乐部服务支持</view><text>当前为交互演示，真实客服尚未接入。</text></view></view><view class="detail-bio">组队订单按约定时长完成；护航订单按指定任务验收。新用户默认无发单或接单资格。组队与护航分别考核，通过对应类型与游戏的考核后，才可发布或接取对应订单。</view><view class="sheet-footnote">模拟数据保存在当前浏览器，不同设备之间独立。</view></view>
    </view></view><view v-if="toast" class="toast"><uni-icons type="info" color="#d9fd88" :size="18"/>{{toast}}</view>
  </view>
</template>

